select to_regclass('public.account_restrictions') is not null as restrictions, to_regclass('public.session_meetings') is not null as meetings, exists(select 1 from information_schema.columns where table_schema='public' and table_name='lesson_sessions' and column_name='meeting_link') as legacy_meetings, to_regprocedure('public.my_teacher_metrics()') is not null as metrics_rpc, to_regprocedure('public.my_teacher_preparation()') is not null as prep_rpc, to_regprocedure('public.my_account_restriction()') is not null as restriction_rpc;
